B=['777777700700077','077077077777077','007007070770770','777777777777070']
# compare each possible vertical shift/orientation with x offset to align B to a substring of A; score matches and 7-on-0 donor diffs
for orient in [0,1]:
 C=B[::-1] if orient else B
 best=[]
